cypress_script:
describe('JavaScript Alerts', () => {
  it('should display an alert and accept it', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Alert').click();
    cy.on('window:alert', (text) => {
      expect(text).to.eq('I am a JS Alert');
    });
    cy.get('#result').should('be.visible');
  });

  it('should display a confirm dialog and accept it', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Confirm').click();
    cy.on('window:confirm', () => true);
    cy.get('#result').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('JavaScript Alerts', () => {
  test('should display an alert and accept it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    page.on('dialog', async dialog => {
      expect(dialog.message()).toBe('I am a JS Alert');
      await dialog.accept();
    });
    await page.click('button:has-text("Click for JS Alert")');
    const result = await page.locator('#result');
    await expect(result).toBeVisible();
  });

  test('should display a confirm dialog and accept it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    page.on('dialog', async dialog => {
      await dialog.accept();
    });
    await page.click('button:has-text("Click for JS Confirm")');
    const result = await page.locator('#result');
    await expect(result).toBeVisible();
  });
});
